import {loadVendor} from './web-store.mjs';
import {leerItemizado} from './avance-model.mjs';
let priceItems=new Map();
const root=document.querySelector('#root'),message=document.querySelector('#message');let token='',user,rows=[],contractors=[];const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
async function api(route='',body){const r=await fetch('/api/payments'+route,{method:body?'POST':'GET',cache:'no-store',headers:{'Content-Type':'application/json','X-Payment-Session':token},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok){if(r.status===401&&token){token='';login();}throw Error(data.error);}return data;}
function login(){root.innerHTML='<h2>Acceso personal</h2><form id="login"><label>Correo electrónico<input type="email" name="username" autocomplete="username" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required></label><button>Entrar</button></form>';root.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const data=await api('/login',Object.fromEntries(new FormData(e.target)));token=data.token;user=data.user;e.target.reset();await load();}catch(e){message.textContent=e.message;}};}
async function load(){const data=await api();let prices;try{prices=await api('/prices');}catch(error){message.textContent=error.message;prices={items:[]};}priceItems=new Map(prices.items.map(i=>[i.code,i]));rows=data.payments;contractors=data.contractors;message.textContent='';root.innerHTML='<p>Usuario: '+esc(user.username)+' · '+esc(user.role)+'</p><button id="logout">Cerrar sesión</button><button id="new">Nuevo estado de pago</button><section id="editor"></section><section><h2>Matriz de precios</h2><p>'+priceItems.size+' partidas del catálogo compartido.</p><label>Cargar Excel Rev01 al catálogo compartido (solo aprobador)<input type="file" id="sharedPrices" accept=".xlsx,.xls"></label><p>Catálogo compartido Rev01. El monto de pago se ingresa por separado del precio unitario.</p></section><h2>Registros</h2>'+rows.map((r,i)=>'<article><h3>'+esc(r.contractor)+' · '+esc(r.period)+'</h3><p>'+esc(r.status)+' · Total: $'+r.amount.toLocaleString('es-CL')+' · Retención: $'+r.retention.toLocaleString('es-CL')+' · Neto: $'+r.net.toLocaleString('es-CL')+'</p><small>'+esc(r.by)+' · '+esc(r.at)+' · versión '+r.version+'</small><p><button data-edit="'+i+'">Ver / editar</button></p></article>').join('');root.querySelector('#logout').onclick=async()=>{try{await api('/logout',{});}finally{token='';rows=[];login();}};root.querySelector('#sharedPrices').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(user.role!=='approver')throw Error('Solo un aprobador puede cargar precios');await loadVendor('xlsx');const parsed=leerItemizado(XLSX.read(await f.arrayBuffer(),{type:'array'}),XLSX),items=[...parsed.items.values()].map(i=>({code:i.code,desc:i.desc,unit:i.unit,pu:i.pu,source:f.name,sourceRow:i.fila}));for(let n=0;n<items.length;n+=100){message.textContent='Cargando '+n+' de '+items.length+' partidas…';await api('/prices',{items:items.slice(n,n+100)});}await load();message.textContent='Catálogo compartido cargado: '+items.length+' partidas.';}catch(error){message.textContent=error.message+' Puedes repetir la carga; los códigos existentes se actualizan.';}};root.querySelector('#new').onclick=()=>edit();root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(rows[Number(b.dataset.edit)]));}
function edit(record={}){const area=root.querySelector('#editor');area.innerHTML='<h2>'+ (record.id?'Editar':'Nuevo')+'</h2><form><label>Subcontratista<select name="contractor" required><option value="">Selecciona un subcontratista</option>'+(record.contractor&&!contractors.some(c=>c.label===record.contractor)?'<option selected>'+esc(record.contractor)+'</option>':'')+contractors.map(c=>'<option value="'+esc(c.label)+'" '+(record.contractor===c.label?'selected':'')+'>'+esc(c.label)+'</option>').join('')+'</select></label><label>Período<input type="month" name="period" value="'+esc(record.period)+'" required></label><h3>Partidas</h3><p>Pulsa Seleccionar partida para abrir todas las alternativas del catálogo.</p><div id="items"></div><button type="button" id="add">Añadir partida</button><label>Retención CLP<input type="number" min="0" step="1" name="retention" value="'+(record.retention||0)+'" required></label><label>Estado<select name="status">'+['Borrador','En revisión','Aprobado','Rechazado'].map(s=>'<option '+(record.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></label><button>Guardar</button></form>';const items=area.querySelector('#items');const add=(item={})=>{const div=document.createElement('div');div.className='item';div.innerHTML='<input readonly placeholder="Selecciona una partida…" aria-label="Partida seleccionada" maxlength="500" value="'+esc(item.description)+'" required><input aria-label="Monto CLP" type="number" min="0" step="1" value="'+(item.amount??'')+'" required><button type="button">Quitar</button>';const hint=document.createElement('small');const showPrice=()=>{const value=div.children[0].value,selected=[...priceItems.values()].find(i=>value===i.code+' · '+i.desc);hint.textContent=selected?'Unidad: '+selected.unit+' · Precio unitario de referencia: $'+Number(selected.pu).toLocaleString('es-CL')+' · Ingresa el monto total de este pago en el campo de monto.':'';};const choose=document.createElement('button');choose.type='button';choose.className='choosePrice';choose.textContent='Seleccionar partida ▾';choose.onclick=()=>openPricePicker(selected=>{div.children[0].value=selected.code+' · '+selected.desc;showPrice();});div.children[0].onclick=()=>choose.click();div.append(choose);showPrice();div.querySelector('button').onclick=()=>div.remove();div.append(hint);items.append(div);};(record.items||[{}]).forEach(add);area.querySelector('#add').onclick=()=>add();area.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if([...items.children].some(div=>!div.children[0].value)){message.textContent='Selecciona una partida del catálogo para cada fila.';return;}b.items=[...items.children].map(div=>({description:div.children[0].value,amount:Number(div.children[1].value)}));b.retention=Number(b.retention);b.id=record.id;b.version=record.version;try{await api('',b);await load();message.textContent='Estado de pago guardado.';}catch(e){message.textContent=e.message;}};area.scrollIntoView({block:'start'});}
function openPricePicker(onSelect){
 const dialog=document.createElement('dialog');dialog.className='pricePicker';dialog.innerHTML='<header><h2>Seleccionar partida</h2><button type="button" class="closePicker" aria-label="Cerrar catálogo">Cerrar ✕</button></header><label>Buscar código o descripción<input class="priceQuery" type="search" placeholder="Ej.: baranda, pintura, 5.1…"></label><p class="priceCount" role="status"></p><div class="priceAlternatives"></div><footer><button type="button" class="prevPrice">Anterior</button><span class="pricePage"></span><button type="button" class="nextPrice">Siguiente</button></footer>';
 document.body.append(dialog);let page=0;const norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),query=dialog.querySelector('.priceQuery'),list=dialog.querySelector('.priceAlternatives');const close=()=>{dialog.close();dialog.remove();};dialog.querySelector('.closePicker').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};
 function draw(){const words=norm(query.value).split(/\s+/).filter(Boolean),matches=[...priceItems.values()].filter(i=>words.every(w=>norm(i.code+' '+i.desc+' '+i.unit).includes(w))).sort((a,b)=>a.code.localeCompare(b.code,'es',{numeric:true})),pages=Math.max(1,Math.ceil(matches.length/50));page=Math.min(page,pages-1);dialog.querySelector('.priceCount').textContent=matches.length+' alternativas de '+priceItems.size+' partidas';list.replaceChildren();for(const item of matches.slice(page*50,page*50+50)){const button=document.createElement('button');button.type='button';button.className='priceAlternative';button.innerHTML='<strong>'+esc(item.code)+' · '+esc(item.desc)+'</strong><small>Unidad: '+esc(item.unit)+' · Precio unitario: $'+esc(Number(item.pu).toLocaleString('es-CL'))+'</small>';button.onclick=()=>{onSelect(item);close();};list.append(button);}if(!matches.length)list.textContent=priceItems.size?'No hay coincidencias. Prueba otra descripción o código.':'No hay partidas cargadas en el catálogo compartido.';dialog.querySelector('.pricePage').textContent=(page+1)+' / '+pages;dialog.querySelector('.prevPrice').disabled=page===0;dialog.querySelector('.nextPrice').disabled=page+1>=pages;list.scrollTop=0;}
 query.oninput=()=>{page=0;draw();};dialog.querySelector('.prevPrice').onclick=()=>{page--;draw();};dialog.querySelector('.nextPrice').onclick=()=>{page++;draw();};draw();dialog.showModal();dialog.querySelector('.closePicker').focus();
}
login();
